import {useEffect,useState} from 'react';import {Plus,Search,Edit2,Trash2,RefreshCw} from 'lucide-react';import api,{message} from '../services/api.js';import Modal from '../components/Modal.jsx';
const empty={title:'',author:'',isbn:'',category:'General',publisher:'',shelf:'',totalCopies:1};
export default function Books(){const [rows,setRows]=useState([]),[q,setQ]=useState(''),[open,setOpen]=useState(false),[edit,setEdit]=useState(null),[form,setForm]=useState(empty),[busy,setBusy]=useState(false),[error,setError]=useState('');async function load(){try{setRows((await api.get('/books',{params:{q}})).data);setError('')}catch(e){setError(message(e))}}useEffect(()=>{const t=setTimeout(load,250);return()=>clearTimeout(t)},[q]);function start(b){setEdit(b);setForm({...b});setOpen(true)}function add(){setEdit(null);setForm(empty);setOpen(true)}async function save(e){e.preventDefault();setBusy(true);setError('');try{if(edit)await api.put(`/books/${edit._id}`,form);else await api.post('/books',form);setOpen(false);await load()}catch(e){setError(message(e))}finally{setBusy(false)}}async function remove(id){if(!confirm('Delete this book?'))return;try{await api.delete(`/books/${id}`);load()}catch(e){setError(message(e))}}return <><div className="page-head"><div><h2>Books</h2><p>Manage titles, copies and catalog details.</p></div><button className="btn primary" onClick={add}><Plus size={17}/>Add book</button></div><div className="toolbar"><div className="search"><Search size={17}/><input placeholder="Search title, author, ISBN, category..." value={q} onChange={e=>setQ(e.target.value)}/></div><button className="icon-btn" onClick={load} title="Refresh"><RefreshCw size={17}/></button></div>{error&&<div className="alert error">{error}</div>}<div className="panel table-wrap"><table><thead><tr><th>Title</th><th>Author</th><th>Category</th><th>ISBN</th><th>Copies</th><th>Shelf</th><th></th></tr></thead><tbody>{rows.map(b=><tr key={b._id}><td><b>{b.title}</b><small>{b.publisher||'—'}</small></td><td>{b.author}</td><td><span className="badge neutral">{b.category}</span></td><td>{b.isbn||'—'}</td><td><span className={b.availableCopies?'badge success':'badge danger'}>{b.availableCopies}/{b.totalCopies}</span></td><td>{b.shelf||'—'}</td><td className="actions"><button className="icon-btn" onClick={()=>start(b)}><Edit2 size={16}/></button><button className="icon-btn danger-icon" onClick={()=>remove(b._id)}><Trash2 size={16}/></button></td></tr>)}{!rows.length&&<tr><td colSpan="7" className="empty">No books found.</td></tr>}</tbody></table></div><Modal open={open} onClose={()=>setOpen(false)} title={edit?'Edit book':'Add book'}><form onSubmit={save} className="form-grid"><label>Title<input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Author<input required value={form.author} onChange={e=>setForm({...form,author:e.target.value})}/></label><label>ISBN<input value={form.isbn} onChange={e=>setForm({...form,isbn:e.target.value})}/></label><label>Category<input value={form.category} onChange={e=>setForm({...form,category:e.target.value})}/></label><label>Publisher<input value={form.publisher} onChange={e=>setForm({...form,publisher:e.target.value})}/></label><label>Shelf / rack<input value={form.shelf} onChange={e=>setForm({...form,shelf:e.target.value})}/></label><label>Copies<input type="number" min="1" required value={form.totalCopies} onChange={e=>setForm({...form,totalCopies:Number(e.target.value)})}/></label>{error&&<div className="alert error full-col">{error}</div>}<div className="modal-actions"><button type="button" className="btn" onClick={()=>setOpen(false)}>Cancel</button><button className="btn primary" disabled={busy}>{busy?'Saving...':'Save book'}</button></div></form></Modal></>}
